RRB.load({"id": "gd-full-7", "exam": "gd", "label": "Group D full mock 7 (100 Q)", "questions": [{"s": "General Science", "t": "Physics", "q": "A hydraulic lift works on which principle?", "o": ["Pascal's law", "Archimedes' principle", "Bernoulli's principle", "Newton's law of gravitation"], "a": 0, "e": "Pascal's law: pressure applied to an enclosed liquid is passed equally in all directions, so a small force on a small piston lifts a heavy load.", "qh": "हाइड्रोलिक लिफ़्ट किस सिद्धांत पर काम करती है?", "oh": ["पास्कल का नियम", "आर्किमिडीज़ का सिद्धांत", "बर्नूली का सिद्धांत", "न्यूटन का गुरुत्वाकर्षण नियम"], "eh": "पास्कल का नियम: बंद द्रव पर लगाया दाब सभी दिशाओं में बराबर फैलता है, इसलिए छोटे पिस्टन पर कम बल से भारी बोझ उठता है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Which is the largest cell known?", "o": ["Human nerve cell", "Red blood cell", "Egg of an ostrich", "Amoeba"], "a": 2, "e": "The ostrich egg (yolk) is the largest single cell; the nerve cell is the longest cell in the human body.", "qh": "ज्ञात कोशिकाओं में सबसे बड़ी कोशिका कौन-सी है?", "oh": ["मानव तंत्रिका कोशिका", "लाल रक्त कोशिका", "शुतुरमुर्ग का अंडा", "अमीबा"], "eh": "शुतुरमुर्ग का अंडा (ज़र्दी) सबसे बड़ी एक कोशिका है; मानव शरीर में तंत्रिका कोशिका सबसे लंबी है।", "level": "easy"}, {"s": "General Science", "t": "Biology", "q": "The normal blood pressure of a healthy adult is about:", "o": ["90/60 mm Hg", "140/100 mm Hg", "120/80 mm Hg", "100/50 mm Hg"], "a": 2, "e": "About 120 mm Hg systolic and 80 mm Hg diastolic is taken as normal.", "qh": "एक स्वस्थ वयस्क का सामान्य रक्तचाप लगभग कितना होता है?", "oh": ["90/60 mm Hg", "140/100 mm Hg", "120/80 mm Hg", "100/50 mm Hg"], "eh": "लगभग 120 mm Hg सिस्टोलिक और 80 mm Hg डायस्टोलिक को सामान्य माना जाता है।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "The loudness of sound is measured in:", "o": ["Hertz", "Decibel", "Newton", "Tesla"], "a": 1, "e": "Loudness (sound level) is measured in decibels (dB); frequency is in hertz.", "qh": "ध्वनि की प्रबलता किसमें मापी जाती है?", "oh": ["हर्ट्ज़", "डेसिबल", "न्यूटन", "टेस्ला"], "eh": "ध्वनि का स्तर डेसिबल (dB) में मापा जाता है; आवृत्ति हर्ट्ज़ में।", "level": "easy"}, {"s": "General Science", "t": "Biology", "q": "Rabies is spread to humans mainly through the bite of:", "o": ["A mosquito", "An infected dog", "A housefly", "A rat flea"], "a": 1, "e": "Rabies is a viral disease spread mostly by bites of infected dogs; the vaccine was developed by Louis Pasteur.", "qh": "रेबीज़ इंसानों में मुख्य रूप से किसके काटने से फैलता है?", "oh": ["मच्छर", "संक्रमित कुत्ते", "घरेलू मक्खी", "चूहे का पिस्सू"], "eh": "रेबीज़ एक विषाणु रोग है जो ज़्यादातर संक्रमित कुत्तों के काटने से फैलता है; इसका टीका लुई पाश्चर ने बनाया।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Water rising in a narrow glass tube against gravity is an example of:", "o": ["Capillary action", "Viscosity", "Diffusion", "Osmosis"], "a": 0, "e": "Capillary action is due to adhesion and surface tension; it also helps oil rise in a lamp wick.", "qh": "पतली काँच की नली में पानी का गुरुत्व के विरुद्ध ऊपर चढ़ना किसका उदाहरण है?", "oh": ["केशिकत्व (कैपिलरी क्रिया)", "श्यानता", "विसरण", "परासरण"], "eh": "केशिकत्व आसंजन और पृष्ठ तनाव के कारण होता है; इसी से दीये की बाती में तेल ऊपर चढ़ता है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "LPG used as cooking gas is mainly a mixture of:", "o": ["Butane and propane", "Methane and ethane", "Hydrogen and oxygen", "Carbon monoxide and hydrogen"], "a": 0, "e": "LPG is chiefly butane and propane; ethyl mercaptan is added so leaks can be smelt.", "qh": "खाना पकाने वाली LPG मुख्य रूप से किनका मिश्रण है?", "oh": ["ब्यूटेन और प्रोपेन", "मीथेन और एथेन", "हाइड्रोजन और ऑक्सीजन", "कार्बन मोनोऑक्साइड और हाइड्रोजन"], "eh": "LPG मुख्य रूप से ब्यूटेन और प्रोपेन है; रिसाव की गंध के लिए एथिल मरकैप्टन मिलाया जाता है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Sodium metal is stored under kerosene because it:", "o": ["Is very heavy", "Melts at room temperature", "Is radioactive", "Reacts vigorously with air and water"], "a": 3, "e": "Sodium reacts quickly with oxygen and moisture (even catching fire), so it is kept in kerosene.", "qh": "सोडियम धातु को मिट्टी के तेल में क्यों रखा जाता है?", "oh": ["क्योंकि यह बहुत भारी है", "क्योंकि यह कमरे के तापमान पर पिघलती है", "क्योंकि यह रेडियोधर्मी है", "क्योंकि यह हवा और पानी से तेज़ी से अभिक्रिया करती है"], "eh": "सोडियम ऑक्सीजन और नमी से जल्दी अभिक्रिया करता है (आग भी पकड़ सकता है), इसलिए इसे मिट्टी के तेल में रखते हैं।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Silk is obtained from the cocoon of the silkworm, which feeds mainly on the leaves of:", "o": ["Neem", "Banyan", "Mango", "Mulberry"], "a": 3, "e": "The mulberry silkworm (Bombyx mori) eats mulberry leaves; rearing silkworms is called sericulture.", "qh": "रेशम, रेशम के कीड़े के कोकून से मिलता है। यह कीड़ा मुख्य रूप से किसकी पत्तियाँ खाता है?", "oh": ["नीम", "बरगद", "आम", "शहतूत"], "eh": "शहतूत रेशम कीट (बॉम्बिक्स मोरी) शहतूत की पत्तियाँ खाता है; रेशम कीट पालन को सेरीकल्चर कहते हैं।", "level": "easy"}, {"s": "General Science", "t": "Biology", "q": "Which of these is an insectivorous plant?", "o": ["Cuscuta", "Pitcher plant", "Mango", "Money plant"], "a": 1, "e": "The pitcher plant traps insects to get nitrogen; Cuscuta (amarbel) is a parasite.", "qh": "इनमें से कौन-सा कीटभक्षी पौधा है?", "oh": ["अमरबेल (कस्कुटा)", "घटपर्णी (पिचर प्लांट)", "आम", "मनी प्लांट"], "eh": "घटपर्णी नाइट्रोजन पाने के लिए कीड़े फँसाती है; अमरबेल परजीवी है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "The muscular sheet that separates the chest cavity from the abdomen and helps in breathing is the:", "o": ["Diaphragm", "Pleura", "Larynx", "Epiglottis"], "a": 0, "e": "When the diaphragm contracts and flattens, the chest cavity enlarges and air is drawn into the lungs.", "qh": "छाती की गुहा को पेट से अलग करने वाली और साँस लेने में मदद करने वाली मांसपेशी की परत क्या कहलाती है?", "oh": ["डायाफ़्राम (मध्यपट)", "फुफ़्फ़ुसावरण (प्लूरा)", "स्वरयंत्र", "एपिग्लॉटिस"], "eh": "डायाफ़्राम सिकुड़कर चपटा होता है तो छाती की गुहा बड़ी होती है और हवा फेफड़ों में खिंचती है।", "level": "tough"}, {"s": "General Science", "t": "Chemistry", "q": "'Heavy water', used as a moderator in some nuclear reactors, is:", "o": ["Hydrogen peroxide (H₂O₂)", "Water with dissolved salts", "Tritium oxide only", "Deuterium oxide (D₂O)"], "a": 3, "e": "Heavy water has deuterium (²H) in place of ordinary hydrogen; it slows down neutrons.", "qh": "कुछ परमाणु रिएक्टरों में मंदक के रूप में इस्तेमाल होने वाला 'भारी जल' क्या है?", "oh": ["हाइड्रोजन पेरॉक्साइड (H₂O₂)", "घुले लवणों वाला पानी", "केवल ट्रिटियम ऑक्साइड", "ड्यूटेरियम ऑक्साइड (D₂O)"], "eh": "भारी जल में साधारण हाइड्रोजन की जगह ड्यूटेरियम (²H) होता है; यह न्यूट्रॉन की रफ़्तार कम करता है।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "Bats find their way in the dark using:", "o": ["Infrared light", "Ultrasonic sound", "Infrasonic sound", "Radio waves"], "a": 1, "e": "Bats emit ultrasonic sounds (above 20 kHz) and locate objects from the echoes (echolocation).", "qh": "चमगादड़ अंधेरे में किसकी मदद से रास्ता ढूँढते हैं?", "oh": ["अवरक्त प्रकाश", "पराश्रव्य (अल्ट्रासोनिक) ध्वनि", "अवश्रव्य ध्वनि", "रेडियो तरंगें"], "eh": "चमगादड़ 20 kHz से ऊँची पराश्रव्य ध्वनि निकालते हैं और गूँज से चीज़ों का पता लगाते हैं।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Cholera is caused by a:", "o": ["Virus", "Fungus", "Protozoan", "Bacterium"], "a": 3, "e": "Cholera is caused by the bacterium Vibrio cholerae, spread through contaminated water.", "qh": "हैजा किससे होता है?", "oh": ["विषाणु (वायरस)", "कवक", "प्रोटोज़ोआ", "जीवाणु (बैक्टीरिया)"], "eh": "हैजा दूषित पानी से फैलने वाले विब्रियो कॉलेरी जीवाणु से होता है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Which instrument is used to see objects above the line of sight, for example in a submarine?", "o": ["Telescope", "Microscope", "Periscope", "Kaleidoscope"], "a": 2, "e": "A periscope uses two plane mirrors (or prisms) at 45° to see over obstacles.", "qh": "पनडुब्बी जैसी जगहों से दृष्टि-रेखा के ऊपर की वस्तुएँ देखने के लिए कौन-सा यंत्र इस्तेमाल होता है?", "oh": ["दूरबीन", "सूक्ष्मदर्शी", "पेरिस्कोप", "बहुरूपदर्शी"], "eh": "पेरिस्कोप में 45° पर लगे दो समतल दर्पण (या प्रिज़्म) होते हैं, जिनसे रुकावट के ऊपर देखा जा सकता है।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "Which was the first fully synthetic fibre?", "o": ["Nylon", "Rayon", "Cotton", "Wool"], "a": 0, "e": "Nylon was made by Wallace Carothers in 1935; rayon is made from cellulose (semi-synthetic).", "qh": "पहला पूरी तरह संश्लेषित (सिंथेटिक) रेशा कौन-सा था?", "oh": ["नायलॉन", "रेयॉन", "कपास", "ऊन"], "eh": "नायलॉन 1935 में वालेस कैरोथर्स ने बनाया; रेयॉन सेल्युलोज़ से बनता है (अर्ध-संश्लेषित)।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "A mirage seen on a hot road is caused by:", "o": ["Dispersion of light", "Total internal reflection of light", "Diffraction of light", "Polarisation of light"], "a": 1, "e": "Air near the hot road is less dense, so light bends and is totally internally reflected, looking like water.", "qh": "गर्म सड़क पर दिखने वाली मरीचिका किस कारण होती है?", "oh": ["प्रकाश के विक्षेपण से", "प्रकाश के पूर्ण आंतरिक परावर्तन से", "प्रकाश के विवर्तन से", "प्रकाश के ध्रुवण से"], "eh": "गर्म सड़क के पास की हवा कम घनी होती है, इसलिए प्रकाश मुड़कर पूर्ण आंतरिक परावर्तित होता है और पानी जैसा दिखता है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Which gas is filled in advertisement signs that glow red-orange?", "o": ["Argon", "Neon", "Chlorine", "Oxygen"], "a": 1, "e": "Neon gives a red-orange glow when electricity passes through it at low pressure.", "qh": "लाल-नारंगी चमकने वाले विज्ञापन बोर्डों में कौन-सी गैस भरी जाती है?", "oh": ["आर्गन", "नियॉन", "क्लोरीन", "ऑक्सीजन"], "eh": "कम दाब पर बिजली गुज़ारने से नियॉन लाल-नारंगी चमकती है।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "Which acid is found in tamarind?", "o": ["Lactic acid", "Oxalic acid", "Formic acid", "Tartaric acid"], "a": 3, "e": "Tamarind and grapes contain tartaric acid.", "qh": "इमली में कौन-सा अम्ल होता है?", "oh": ["लैक्टिक अम्ल", "ऑक्सैलिक अम्ल", "फ़ॉर्मिक अम्ल", "टार्टरिक अम्ल"], "eh": "इमली और अंगूर में टार्टरिक अम्ल होता है।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "Which element is the most abundant in the Earth's crust?", "o": ["Silicon", "Aluminium", "Iron", "Oxygen"], "a": 3, "e": "By mass the crust is about 46% oxygen, then silicon (~28%) and aluminium (~8%).", "qh": "पृथ्वी की पपड़ी में सबसे ज़्यादा पाया जाने वाला तत्व कौन-सा है?", "oh": ["सिलिकॉन", "एल्युमिनियम", "लोहा", "ऑक्सीजन"], "eh": "द्रव्यमान के हिसाब से पपड़ी में लगभग 46% ऑक्सीजन, फिर सिलिकॉन (~28%) और एल्युमिनियम (~8%) है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "A substance that speeds up a chemical reaction without itself being used up is called a:", "o": ["Reactant", "Product", "Catalyst", "Inhibitor"], "a": 2, "e": "A catalyst lowers the activation energy and is recovered unchanged; an inhibitor slows a reaction.", "qh": "जो पदार्थ खुद खर्च हुए बिना रासायनिक अभिक्रिया को तेज़ करता है, वह कहलाता है:", "oh": ["अभिकारक", "उत्पाद", "उत्प्रेरक", "अवरोधक"], "eh": "उत्प्रेरक सक्रियण ऊर्जा घटाता है और बिना बदले वापस मिल जाता है; अवरोधक अभिक्रिया धीमी करता है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "Energy in the Sun is produced mainly by:", "o": ["Nuclear fusion", "Nuclear fission", "Burning of coal", "Chemical reactions of oxygen"], "a": 0, "e": "In the Sun's core, hydrogen nuclei fuse to form helium and release huge energy.", "qh": "सूर्य में ऊर्जा मुख्य रूप से किससे बनती है?", "oh": ["नाभिकीय संलयन", "नाभिकीय विखंडन", "कोयला जलने से", "ऑक्सीजन की रासायनिक अभिक्रियाओं से"], "eh": "सूर्य के केंद्र में हाइड्रोजन नाभिक जुड़कर हीलियम बनाते हैं और बहुत ऊर्जा छोड़ते हैं।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "The frequency of the AC mains supply in India is:", "o": ["60 Hz", "100 Hz", "220 Hz", "50 Hz"], "a": 3, "e": "India's mains supply is 230 V AC at 50 Hz; the USA uses 60 Hz.", "qh": "भारत में घरेलू AC बिजली आपूर्ति की आवृत्ति कितनी है?", "oh": ["60 Hz", "100 Hz", "220 Hz", "50 Hz"], "eh": "भारत में मेन सप्लाई 230 V AC, 50 Hz है; अमेरिका में 60 Hz है।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "An aeroplane wing gets lift because air moves faster over its curved upper surface, lowering the pressure there. This is explained by:", "o": ["Pascal's law", "Bernoulli's principle", "Hooke's law", "Ohm's law"], "a": 1, "e": "Bernoulli's principle: where a fluid moves faster its pressure is lower, so the wing is pushed up.", "qh": "हवाई जहाज़ के पंख को उठान इसलिए मिलता है कि ऊपर की घुमावदार सतह पर हवा तेज़ चलती है और वहाँ दाब घटता है। इसे कौन-सा सिद्धांत समझाता है?", "oh": ["पास्कल का नियम", "बर्नूली का सिद्धांत", "हुक का नियम", "ओम का नियम"], "eh": "बर्नूली का सिद्धांत: जहाँ द्रव तेज़ बहता है वहाँ दाब कम होता है, इसलिए पंख ऊपर धकेला जाता है।", "level": "tough"}, {"s": "General Science", "t": "Biology", "q": "Which enzyme in the stomach begins the digestion of proteins?", "o": ["Amylase", "Lipase", "Pepsin", "Trypsin"], "a": 2, "e": "Pepsin works in the acidic stomach; trypsin continues protein digestion in the small intestine.", "qh": "आमाशय में प्रोटीन का पाचन कौन-सा एंज़ाइम शुरू करता है?", "oh": ["एमाइलेज़", "लाइपेज़", "पेप्सिन", "ट्रिप्सिन"], "eh": "पेप्सिन अम्लीय आमाशय में काम करता है; छोटी आँत में ट्रिप्सिन प्रोटीन का पाचन आगे बढ़ाता है।", "level": "medium"}, {"s": "Mathematics", "t": "Geometry", "q": "In triangle ABC, ∠A = 64°. The bisectors of ∠B and ∠C meet at O. What is ∠BOC?", "o": ["58°", "116°", "132°", "122°"], "a": 3, "e": "∠BOC = 90° + ∠A/2 = 90° + 32° = 122°.", "qh": "त्रिभुज ABC में ∠A = 64° है। ∠B और ∠C के समद्विभाजक O पर मिलते हैं। ∠BOC कितना है?", "oh": ["58°", "116°", "132°", "122°"], "eh": "∠BOC = 90° + ∠A/2 = 90° + 32° = 122°।", "level": "tough"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 7 consecutive even numbers is 48. What is the smallest of them?", "o": ["42", "40", "44", "54"], "a": 0, "e": "The average is the middle number 48; there are 3 numbers on each side with gap 2 → smallest = 42.", "qh": "7 लगातार सम संख्याओं का औसत 48 है। उनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["42", "40", "44", "54"], "eh": "औसत ही बीच वाली संख्या 48 है; दोनों ओर 3 संख्याएँ, अंतर 2 → उत्तर = 42।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "The cost price of a pressure cooker is ₹2,700. At what price must it be marked so that after allowing a 10% discount, the seller gains 20%?", "o": ["₹3,660", "₹3,564", "₹3,600", "₹3,560"], "a": 2, "e": "SP = ₹2,700 × 120/100 = ₹3,240; MP = SP × 100/90 = ₹3,600.", "qh": "एक प्रेशर कुकर का क्रय मूल्य ₹2,700 है। इस पर कितना अंकित मूल्य लिखा जाए कि 10% छूट देने के बाद भी विक्रेता को 20% लाभ हो?", "oh": ["₹3,660", "₹3,564", "₹3,600", "₹3,560"], "eh": "विक्रय मूल्य = ₹2,700 × 120/100 = ₹3,240; अंकित मूल्य = विक्रय मूल्य × 100/90 = ₹3,600।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 9 consecutive numbers is 20. What is the smallest of them?", "o": ["24", "16", "29", "15"], "a": 1, "e": "The average is the middle number 20; there are 4 numbers on each side with gap 1 → smallest = 16.", "qh": "9 लगातार संख्याओं का औसत 20 है। उनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["24", "16", "29", "15"], "eh": "औसत ही बीच वाली संख्या 20 है; दोनों ओर 4 संख्याएँ, अंतर 1 → उत्तर = 16।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the total surface area of a solid hemisphere with radius 7 cm? (Take π = 22/7)", "o": ["484 cm²", "924 cm²", "418 cm²", "462 cm²"], "a": 3, "e": "3πr² = 3 × 22/7 × 7² = 462 cm².", "qh": "7 cm त्रिज्या वाले ठोस अर्धगोले का कुल पृष्ठीय क्षेत्रफल कितना है? (π = 22/7 लें)", "oh": ["484 cm²", "924 cm²", "418 cm²", "462 cm²"], "eh": "3πr² = 3 × 22/7 × 7² = 462 cm²।", "level": "tough"}, {"s": "Mathematics", "t": "Simplification", "q": "What is the value of √4624 + ∛1331?", "o": ["158", "80", "79", "77"], "a": 2, "e": "√4624 = 68, ∛1331 = 11; sum = 79.", "qh": "√4624 + ∛1331 का मान क्या है?", "oh": ["158", "80", "79", "77"], "eh": "√4624 = 68, ∛1331 = 11; योग = 79।", "level": "tough"}, {"s": "Mathematics", "t": "Percentage", "q": "A number is increased by 10%, then decreased by 30%, and then increased by 5%. The result is 3234. What was the original number?", "o": ["4000", "3800", "3234", "4400"], "a": 0, "e": "Original × 1617/2000 = 3234 → original = 3234 ÷ 1617/2000 = 4000.", "qh": "एक संख्या को पहले 10% बढ़ाया, फिर 30% घटाया, और फिर 5% बढ़ाया। नतीजा 3234 आया। मूल संख्या क्या थी?", "oh": ["4000", "3800", "3234", "4400"], "eh": "मूल संख्या × 1617/2000 = 3234 → मूल संख्या = 3234 ÷ 1617/2000 = 4000।", "level": "tough"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "An amount is divided among Ravi, Vikas and Rahul in the ratio 3 : 5 : 7. If Rahul gets ₹3,000 more than Ravi, what is Vikas's share?", "o": ["₹4,500", "₹3,750", "₹5,250", "₹7,500"], "a": 1, "e": "(7 − 3) parts = ₹3,000 → 1 part = ₹750; Vikas = 5 × ₹750 = ₹3,750.", "qh": "एक रकम को रवि, विकास और राहुल में 3 : 5 : 7 के अनुपात में बाँटा गया। अगर राहुल को रवि से ₹3,000 ज़्यादा मिलते हैं, तो विकास का हिस्सा कितना है?", "oh": ["₹4,500", "₹3,750", "₹5,250", "₹7,500"], "eh": "(7 − 3) भाग = ₹3,000 → 1 भाग = ₹750; विकास = 5 × ₹750 = ₹3,750।", "level": "medium"}, {"s": "Mathematics", "t": "Interest", "q": "What is the difference between the compound interest and simple interest on ₹10,000 for 2 years at 4% per annum (compounded annually)?", "o": ["₹26", "₹784", "₹400", "₹16"], "a": 3, "e": "For 2 years, CI − SI = P(R/100)² = ₹10,000 × (4/100)² = ₹16.", "qh": "₹10,000 पर 4% वार्षिक दर से 2 साल के चक्रवृद्धि ब्याज (वार्षिक) और साधारण ब्याज का अंतर क्या है?", "oh": ["₹26", "₹784", "₹400", "₹16"], "eh": "2 साल के लिए CI − SI = P(R/100)² = ₹10,000 × (4/100)² = ₹16।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "How many factors (divisors) does 144 have?", "o": ["19", "15", "17", "4"], "a": 1, "e": "144 = 2^4 × 3^2; number of factors = (4+1) × (2+1) = 15.", "qh": "144 के कितने गुणनखंड (भाजक) हैं?", "oh": ["19", "15", "17", "4"], "eh": "144 = 2^4 × 3^2; गुणनखंडों की संख्या = (4+1) × (2+1) = 15।", "level": "tough"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 30% of 680 − 25% of 180 = ?", "o": ["159", "154", "169", "161"], "a": 0, "e": "30% of 680 = 204; 25% of 180 = 45; result = 159.", "qh": "सरल कीजिए: 680 का 30% − 180 का 25% = ?", "oh": ["159", "154", "169", "161"], "eh": "680 का 30% = 204; 180 का 25% = 45; परिणाम = 159।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "In an examination, a student who scores 32% marks fails by 75 marks, while another student who scores 48% marks gets 21 marks more than the pass marks. What are the maximum marks?", "o": ["600", "534", "500", "650"], "a": 0, "e": "(48 − 32)% of maximum = 75 + 21 = 96 → maximum = 96 × 100/16 = 600.", "qh": "एक परीक्षा में 32% अंक पाने वाला छात्र 75 अंकों से फ़ेल होता है, जबकि 48% अंक पाने वाले छात्र को पास अंकों से 21 अंक ज़्यादा मिलते हैं। पूरे अंक कितने हैं?", "oh": ["600", "534", "500", "650"], "eh": "पूरे अंकों का (48 − 32)% = 75 + 21 = 96 → पूरे अंक = 96 × 100/16 = 600।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Manoj starts a business with ₹45,000. After 6 months Rohit joins with ₹25,000, and 8 months after the start Amit joins with ₹60,000. Out of an annual profit of ₹46,500, what is Rohit's share?", "o": ["₹8,500", "₹7,500", "₹15,500", "₹9,500"], "a": 1, "e": "Capital × months = 45000×12 : 25000×6 : 60000×4 = 18 : 5 : 8. Share = 5/31 × ₹46,500 = ₹7,500.", "qh": "मनोज ₹45,000 से कारोबार शुरू करता है। 6 महीने बाद रोहित ₹25,000 लेकर जुड़ता है, और शुरुआत से 8 महीने बाद अमित ₹60,000 लेकर जुड़ता है। साल के ₹46,500 लाभ में रोहित का हिस्सा कितना है?", "oh": ["₹8,500", "₹7,500", "₹15,500", "₹9,500"], "eh": "पूँजी × महीने = 45000×12 : 25000×6 : 60000×4 = 18 : 5 : 8। हिस्सा = 5/31 × ₹46,500 = ₹7,500।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "What is the remainder when 471 + 930 + 143 is divided by 6?", "o": ["2", "3", "4", "5"], "a": 0, "e": "Remainders: 3 + 0 + 5 = 8; 8 mod 6 = 2.", "qh": "471 + 930 + 143 को 6 से भाग देने पर शेषफल क्या होगा?", "oh": ["2", "3", "4", "5"], "eh": "शेषफल: 3 + 0 + 5 = 8; इसे 6 से भाग देने पर शेष 2।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "20 workers can build a wall in 12 days. How many days will 40 workers take to build the same wall?", "o": ["5 days", "6 days", "8 days", "24 days"], "a": 1, "e": "Work = 20 × 12 = 240 worker-days. Days = 240/40 = 6.", "qh": "20 मज़दूर एक दीवार 12 दिन में बना सकते हैं। 40 मज़दूर वही दीवार कितने दिन में बनाएँगे?", "oh": ["5 दिन", "6 दिन", "8 दिन", "24 दिन"], "eh": "काम = 20 × 12 = 240 मज़दूर-दिन। दिन = 240/40 = 6।", "level": "easy"}, {"s": "Mathematics", "t": "Ages", "q": "The present ages of Priya and Sapna are in the ratio 5 : 7. After 4 years, the ratio will be 11 : 15. What is Sapna's present age?", "o": ["56 years", "92 years", "60 years", "40 years"], "a": 0, "e": "(5x + 4)/(7x + 4) = 11/15 → x = 8; age = 7 × 8 = 56 years.", "qh": "प्रिया और सपना की अभी की आयु का अनुपात 5 : 7 है। 4 साल बाद यह अनुपात 11 : 15 हो जाएगा। सपना की अभी की आयु कितनी है?", "oh": ["56 साल", "92 साल", "60 साल", "40 साल"], "eh": "(5x + 4)/(7x + 4) = 11/15 → x = 8; आयु = 7 × 8 = 56 साल।", "level": "tough"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A boat whose speed in still water is 18 km/h goes some distance downstream and comes back upstream in 9 hours in all. If the stream flows at 4 km/h, what is the one-way distance?", "o": ["81 km", "154 km", "77 km", "99 km"], "a": 2, "e": "D/22 + D/14 = 9 → D = 9 × 22 × 14/36 = 77 km.", "qh": "शांत पानी में 18 km/h की रफ़्तार वाली एक नाव धारा के साथ कुछ दूरी जाकर धारा के उलटे लौटती है, कुल 9 घंटे में। धारा की रफ़्तार 4 km/h हो, तो एक तरफ़ की दूरी कितनी है?", "oh": ["81 km", "154 km", "77 km", "99 km"], "eh": "D/22 + D/14 = 9 → D = 9 × 22 × 14/36 = 77 km।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The incomes of Ajay and Ravi are in the ratio 3 : 2 and their expenditures are in the ratio 7 : 4. If each of them saves ₹1,000, what is Ajay's income?", "o": ["₹5,500", "₹3,500", "₹3,000", "₹4,500"], "a": 3, "e": "3x − 7y = 2x − 4y = 1000 → 1x = 3y. Solving: x = 1500, y = 500, so income = 3 × 1500 = ₹4,500.", "qh": "अजय और रवि की आय का अनुपात 3 : 2 और खर्च का अनुपात 7 : 4 है। अगर दोनों ₹1,000 बचाते हैं, तो अजय की आय कितनी है?", "oh": ["₹5,500", "₹3,500", "₹3,000", "₹4,500"], "eh": "3x − 7y = 2x − 4y = 1000 → 1x = 3y। हल करने पर x = 1500, y = 500, आय = 3 × 1500 = ₹4,500।", "level": "medium"}, {"s": "Mathematics", "t": "Trigonometry", "q": "Find the value of tan 45° + cos² 30°.", "o": ["5/4", "-7/4", "7/4", "11/4"], "a": 2, "e": "Put standard values: tan 45° = 1, cos² 30° = 3/4 → value = 7/4.", "qh": "tan 45° + cos² 30° का मान ज्ञात कीजिए।", "oh": ["5/4", "-7/4", "7/4", "11/4"], "eh": "मानक मान रखें: tan 45° = 1, cos² 30° = 3/4 → मान = 7/4।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "24 workers can build a wall in 12 days. How many days will 8 workers take to build the same wall?", "o": ["38 days", "4 days", "36 days", "5 days"], "a": 2, "e": "Work = 24 × 12 = 288 worker-days. Days = 288/8 = 36.", "qh": "24 मज़दूर एक दीवार 12 दिन में बना सकते हैं। 8 मज़दूर वही दीवार कितने दिन में बनाएँगे?", "oh": ["38 दिन", "4 दिन", "36 दिन", "5 दिन"], "eh": "काम = 24 × 12 = 288 मज़दूर-दिन। दिन = 288/8 = 36।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Rahul bought a used motorcycle for ₹19,000 and spent ₹1,000 on servicing. He sold it for ₹23,000. What is his profit percentage?", "o": ["20%", "15%", "15 15/19%", "21 1/19%"], "a": 1, "e": "Total CP = ₹19,000 + ₹1,000 = ₹20,000; profit = ₹3,000; profit % = ₹3,000/₹20,000 × 100 = 15%.", "qh": "राहुल ने एक पुरानी मोटरसाइकिल ₹19,000 में खरीदा और ₹1,000 सर्विसिंग पर खर्च किए। उसने इसे ₹23,000 में बेचा। उसका लाभ प्रतिशत क्या है?", "oh": ["20%", "15%", "15 15/19%", "21 1/19%"], "eh": "कुल क्रय मूल्य = ₹19,000 + ₹1,000 = ₹20,000; लाभ = ₹3,000; लाभ % = ₹3,000/₹20,000 × 100 = 15%।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "By selling a mixer-grinder for ₹2,080, a man loses 20%. At what price should he sell it to gain 15%?", "o": ["₹2,392", "₹2,990", "₹2,808", "₹2,600"], "a": 1, "e": "CP = ₹2,080 × 100/80 = ₹2,600; required SP = ₹2,600 × 115/100 = ₹2,990.", "qh": "एक मिक्सर-ग्राइंडर ₹2,080 में बेचने पर एक व्यक्ति को 20% हानि होती है। 15% लाभ के लिए उसे इसे किस दाम पर बेचना चाहिए?", "oh": ["₹2,392", "₹2,990", "₹2,808", "₹2,600"], "eh": "क्रय मूल्य = ₹2,080 × 100/80 = ₹2,600; ज़रूरी विक्रय मूल्य = ₹2,600 × 115/100 = ₹2,990।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "Two trains 200 m and 250 m long are running in the same direction on parallel tracks at 36 km/h and 27 km/h. In how many seconds will they completely cross each other?", "o": ["180/7 seconds", "12.5 seconds", "360 seconds", "180 seconds"], "a": 3, "e": "Relative speed = 36 − 27 = 9 km/h = 2.5 m/s. Time = (200 + 250)/2.5 = 180 s.", "qh": "200 m और 250 m लंबी दो ट्रेनें समानांतर पटरियों पर एक ही दिशा में 36 km/h और 27 km/h की रफ़्तार से चल रही हैं। वे एक-दूसरे को पूरी तरह कितने सेकंड में पार करेंगी?", "oh": ["180/7 सेकंड", "12.5 सेकंड", "360 सेकंड", "180 सेकंड"], "eh": "सापेक्ष रफ़्तार = 36 − 27 = 9 km/h = 2.5 m/s। समय = (200 + 250)/2.5 = 180 सेकंड।", "level": "tough"}, {"s": "Mathematics", "t": "Algebra", "q": "If a = 3, b = 11 and c = 5, what is the value of a² + b² + c² − ab − bc − ca?", "o": ["50", "52", "155", "104"], "a": 1, "e": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[64 + 36 + 4] = 52.", "qh": "अगर a = 3, b = 11 और c = 5 है, तो a² + b² + c² − ab − bc − ca का मान क्या है?", "oh": ["50", "52", "155", "104"], "eh": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[64 + 36 + 4] = 52।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "A rectangular field is 80 m long and 60 m wide. A path 2.5 m wide is built all around it on the outside. What is the area of the path?", "o": ["675 m²", "700 m²", "725 m²", "745 m²"], "a": 2, "e": "(80 + 5) × (60 + 5) − 80 × 60 = 725 m².", "qh": "एक आयताकार मैदान 80 m लंबा और 60 m चौड़ा है। उसके चारों ओर बाहर की तरफ़ 2.5 m चौड़ा रास्ता बना है। रास्ते का क्षेत्रफल कितना है?", "oh": ["675 m²", "700 m²", "725 m²", "745 m²"], "eh": "(80 + 5) × (60 + 5) − 80 × 60 = 725 m²।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nSTF, QRJ, OPN, MNR, ?", "o": ["KLW", "KLV", "KLX", "JLV"], "a": 1, "e": "Letter positions move by −2, −2, +4 (for 1st, 2nd, 3rd letters). So ? = KLV.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nSTF, QRJ, OPN, MNR, ?", "oh": ["KLW", "KLV", "KLX", "JLV"], "eh": "अक्षरों की स्थिति −2, −2, +4 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = KLV।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n3 1 1 6 3 2 6 3 7 7 4 5 2 2 6 9 2 7 4 8 1 8 4 5 7\nHow many even digits are there, each of which is immediately preceded by an odd digit AND immediately followed by a digit greater than 5?", "o": ["4", "2", "3", "6"], "a": 2, "e": "Matching groups: 3 2 6, 9 2 7, 7 4 8 → 3.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n3 1 1 6 3 2 6 3 7 7 4 5 2 2 6 9 2 7 4 8 1 8 4 5 7\nऐसे कितने सम अंक हैं, जिनके ठीक पहले विषम अंक हो और ठीक बाद 5 से बड़ा अंक हो?", "oh": ["4", "2", "3", "6"], "eh": "शर्त पूरी करने वाले समूह: 3 2 6, 9 2 7, 7 4 8 → 3।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "M, L, S, K, U and B are sitting in a row, all facing North.\nM and U sit next to each other.\nExactly 4 persons sit between S and K.\nB sits second to the right of M.\nL and S sit next to each other.\nL is not an immediate neighbour of M.\nM is not an immediate neighbour of S.\nExactly 1 person sits between B and M.\nWho sits at the extreme right end?", "o": ["U", "S", "M", "B"], "a": 1, "e": "Only one order fits all clues (left to right): K M U B L S. Answer: S.", "qh": "M, L, S, K, U और B एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nM और U पास-पास बैठे हैं।\nS और K के बीच ठीक 4 व्यक्ति बैठे हैं।\nB, M के दाईं ओर दूसरे स्थान पर बैठा है।\nL और S पास-पास बैठे हैं।\nL, M का ठीक पड़ोसी नहीं है।\nM, S का ठीक पड़ोसी नहीं है।\nB और M के बीच ठीक 1 व्यक्ति बैठे हैं।\nसबसे दाएँ छोर पर कौन बैठा है?", "oh": ["U", "S", "M", "B"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): K M U B L S। उत्तर: S।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mirror Image", "q": "Which of the following words has all its letters looking the same in a mirror image (mirror placed to the right)? (Capital letters.)", "o": ["HOT", "HAVOC", "DICE", "HOBBIES"], "a": 0, "e": "In a side mirror, letters A, H, I, M, O, T, U, V, W, X, Y look the same. Every letter of HOT is from this group.", "qh": "नीचे दिए शब्दों में से किस शब्द के सभी अक्षर दर्पण प्रतिबिंब (दर्पण दाईं ओर रखा हो) में वैसे ही दिखेंगे? (बड़े अंग्रेज़ी अक्षर।)", "oh": ["HOT", "HAVOC", "DICE", "HOBBIES"], "eh": "बगल के दर्पण में A, H, I, M, O, T, U, V, W, X, Y वैसे ही दिखते हैं। HOT के सारे अक्षर इसी समूह के हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nQSRO : UUVN :: MMDW : ?", "o": ["VHOQ", "IKZX", "QOHV", "QOHW"], "a": 2, "e": "Each letter moves +4, +2, +4, -1 in order. MMDW → QOHV.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nQSRO : UUVN :: MMDW : ?", "oh": ["VHOQ", "IKZX", "QOHV", "QOHW"], "eh": "हर अक्षर क्रम से +4, +2, +4, -1 खिसकता है। MMDW → QOHV।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: All students who scored above 90% will get a free laptop from the school.\nConclusions:\nI. Some students of the school may get a free laptop.\nII. A student who scored 85% will also get a laptop.", "o": ["Only conclusion II follows", "Only conclusion I follows", "Both I and II follow", "Neither I nor II follows"], "a": 1, "e": "Students above 90% get a laptop, so I follows. 85% is below the limit, so II does not.", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: 90% से ज़्यादा अंक पाने वाले सभी छात्रों को स्कूल से मुफ़्त लैपटॉप मिलेगा।\nनिष्कर्ष:\nI. स्कूल के कुछ छात्रों को मुफ़्त लैपटॉप मिल सकता है।\nII. 85% अंक पाने वाले छात्र को भी लैपटॉप मिलेगा।", "oh": ["केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है", "I और II दोनों सही हैं", "न I सही है, न II"], "eh": "90% से ऊपर वालों को लैपटॉप मिलेगा, इसलिए I सही। 85% सीमा से कम है, इसलिए II नहीं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'cold milk very' is written as 'gu bo fe',\n'is cold tree' is written as 'gu we ni',\n'milk city is' is written as 'pu we bo',\nWhat is the code for 'cold'?", "o": ["gu", "bo", "fe", "we"], "a": 0, "e": "Compare the sentences: common words and common codes match. This gives 'cold' = 'gu'.", "qh": "एक कोड भाषा में:\n'cold milk very' को 'gu bo fe' लिखा जाता है,\n'is cold tree' को 'gu we ni' लिखा जाता है,\n'milk city is' को 'pu we bo' लिखा जाता है,\n'cold' का कोड क्या है?", "oh": ["gu", "bo", "fe", "we"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'cold' = 'gu' मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "What is the angle between the hour hand and the minute hand of a clock at 12:30?", "o": ["172.5°", "180°", "165°", "170°"], "a": 2, "e": "Angle = |30H − 5.5M| = |30×12 − 5.5×30| = 195° → smaller angle = 165°.", "qh": "12:30 बजे घड़ी की घंटे और मिनट की सुई के बीच कितना कोण होगा?", "oh": ["172.5°", "180°", "165°", "170°"], "eh": "कोण = |30H − 5.5M| = |30×12 − 5.5×30| = 195° → छोटा कोण = 165°।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo pens are clocks.\nNo clocks are birds.\nConclusions:\nI. Some clocks are not pens.\nII. All clocks are pens.", "o": ["Only conclusion I follows", "Both I and II follow", "Only conclusion II follows", "Neither I nor II follows"], "a": 0, "e": "Conclusion I is true in every possible diagram; II is not.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी पेन घड़ियाँ नहीं है।\nकोई भी घड़ियाँ पक्षी नहीं है।\nनिष्कर्ष:\nI. कुछ घड़ियाँ पेन नहीं हैं।\nII. सभी घड़ियाँ पेन हैं।", "oh": ["केवल निष्कर्ष I सही है", "I और II दोनों सही हैं", "केवल निष्कर्ष II सही है", "न I सही है, न II"], "eh": "निष्कर्ष I हर संभव आरेख में सही है; II नहीं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Amit starts from point P, walks 2 km towards North, then turns right and walks 15 km, then turns right and walks 6 km, then turns right and walks 12 km. How far is Amit from point P now?", "o": ["35 km", "5 km", "7 km", "4 km"], "a": 1, "e": "Net East–West = +3 km, net North–South = -4 km; distance = √(3² + -4²) = 5 km.", "qh": "अमित बिंदु P से शुरू करके उत्तर की ओर 2 km चलता है, फिर दाएँ मुड़कर 15 km चलता है, फिर दाएँ मुड़कर 6 km चलता है, फिर दाएँ मुड़कर 12 km चलता है। अब अमित बिंदु P से कितनी दूर है?", "oh": ["35 km", "5 km", "7 km", "4 km"], "eh": "कुल पूर्व–पश्चिम = +3 km, कुल उत्तर–दक्षिण = -4 km; दूरी = √(3² + -4²) = 5 km।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "D, K, M, R, Q and A are sitting around a circular table, all facing the centre.\nQ sits second to the right of M.\nD is not an immediate neighbour of M.\nA is an immediate neighbour of D.\nD sits second to the right of K.\nWho sits to the immediate right of M?", "o": ["A", "Q", "R", "K"], "a": 3, "e": "Only one arrangement fits. Going to the right (anticlockwise) from M: M → K → Q → D → A → R. Answer: K.", "qh": "D, K, M, R, Q और A एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nQ, M के दाईं ओर दूसरे स्थान पर बैठा है।\nD, M का ठीक पड़ोसी नहीं है।\nA, D का ठीक पड़ोसी है।\nD, K के दाईं ओर दूसरे स्थान पर बैठा है।\nM के ठीक दाईं ओर कौन बैठा है?", "oh": ["A", "Q", "R", "K"], "eh": "केवल एक व्यवस्था बैठती है। M से दाईं ओर (घड़ी की उलटी दिशा में) चलें: M → K → Q → D → A → R। उत्तर: K।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nThermometer : Temperature :: Barometer : ?", "o": ["Rain", "Pressure", "Wind", "Height"], "a": 1, "e": "Relation: 'measures'. Thermometer – Temperature, so Barometer – Pressure.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nथर्मामीटर : तापमान :: बैरोमीटर : ?", "oh": ["बारिश", "दाब", "हवा", "ऊँचाई"], "eh": "संबंध: 'मापता है'। थर्मामीटर – तापमान, इसलिए बैरोमीटर – दाब।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n8 : 80 :: 6 : ?", "o": ["60", "36", "42", "48"], "a": 3, "e": "Rule: x → x(x + 2). 8 → 80, so 6 → 48.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n8 : 80 :: 6 : ?", "oh": ["60", "36", "42", "48"], "eh": "नियम: x → x(x + 2)। 8 → 80, इसलिए 6 → 48।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Rahul starts from point P, walks 3 km towards East, then turns right and walks 4 km, then turns right and walks 3 km, then turns right and walks 10 km. How far is Rahul from point P now?", "o": ["8 km", "5 km", "6 km", "20 km"], "a": 2, "e": "Net East–West = +0 km, net North–South = +6 km; distance = √(0² + 6²) = 6 km.", "qh": "राहुल बिंदु P से शुरू करके पूर्व की ओर 3 km चलता है, फिर दाएँ मुड़कर 4 km चलता है, फिर दाएँ मुड़कर 3 km चलता है, फिर दाएँ मुड़कर 10 km चलता है। अब राहुल बिंदु P से कितनी दूर है?", "oh": ["8 km", "5 km", "6 km", "20 km"], "eh": "कुल पूर्व–पश्चिम = +0 km, कुल उत्तर–दक्षिण = +6 km; दूरी = √(0² + 6²) = 6 km।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nDG, HK, LO, PS, ?", "o": ["TW", "VW", "UW", "TV"], "a": 0, "e": "Letter positions move by +4, +4 (for 1st, 2nd letters). So ? = TW.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nDG, HK, LO, PS, ?", "oh": ["TW", "VW", "UW", "TV"], "eh": "अक्षरों की स्थिति +4, +4 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = TW।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nI3Z, K8W, M13T, O18Q, ?", "o": ["Q25N", "R23N", "Q23O", "Q23N"], "a": 3, "e": "First letter +2; number: add 5; last letter -3. So ? = Q23N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nI3Z, K8W, M13T, O18Q, ?", "oh": ["Q25N", "R23N", "Q23O", "Q23N"], "eh": "पहला अक्षर +2; संख्या: 5 जोड़ें; आखिरी अक्षर -3। इसलिए ? = Q23N।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "S, C, H, B and Q are sitting around a circular table, all facing the centre.\nH is an immediate neighbour of S.\nB is an immediate neighbour of C.\nH sits immediately to the left of Q.\nB sits second to the right of Q.\nWho sits to the immediate right of C?", "o": ["S", "H", "B", "Q"], "a": 2, "e": "Only one arrangement fits. Going to the right (anticlockwise) from C: C → B → S → H → Q. Answer: B.", "qh": "S, C, H, B और Q एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nH, S का ठीक पड़ोसी है।\nB, C का ठीक पड़ोसी है।\nH, Q के ठीक बाईं ओर बैठा है।\nB, Q के दाईं ओर दूसरे स्थान पर बैठा है।\nC के ठीक दाईं ओर कौन बैठा है?", "oh": ["S", "H", "B", "Q"], "eh": "केवल एक व्यवस्था बैठती है। C से दाईं ओर (घड़ी की उलटी दिशा में) चलें: C → B → S → H → Q। उत्तर: B।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "F is the son of A. A is the son of H. H is the mother of Q. Q is the son of T. How is F related to T?", "o": ["Grandson", "Son-in-law", "Grandfather", "Father"], "a": 0, "e": "Draw the family tree: F → A: son; A → H: son; H → Q: mother; Q → T: son. So F is the grandson of T.", "qh": "F, A का बेटा है। A, H का बेटा है। H, Q की माँ है। Q, T का बेटा है। F का T से क्या संबंध है?", "oh": ["पोता/नाती", "दामाद", "दादा/नाना", "पिता"], "eh": "परिवार का चार्ट बनाएँ: F → A: बेटा; A → H: बेटा; H → Q: माँ; Q → T: बेटा। इसलिए F, T का पोता/नाती है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n954   852   371   845   891\nIf the digits in each number are arranged in descending order within the number, what is the middle digit of the number that is third from the top when the new numbers are arranged in ascending order?", "o": ["8", "7", "5", "6"], "a": 2, "e": "New numbers: 954, 852, 731, 854, 981; ascending: 731, 852, 854, 954, 981; third = 854; middle digit = 5.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n954   852   371   845   891\nअगर हर संख्या के अंकों को उसी संख्या के अंदर घटते क्रम में लगाया जाए, और फिर नई संख्याओं को बढ़ते क्रम में लगाया जाए, तो ऊपर से तीसरी संख्या का बीच वाला अंक क्या होगा?", "oh": ["8", "7", "5", "6"], "eh": "नई संख्याएँ: 954, 852, 731, 854, 981; बढ़ता क्रम: 731, 852, 854, 954, 981; तीसरी = 854; बीच का अंक = 5।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n5, 14, 41, 122, 365, ?", "o": ["730", "1097", "1094", "1099"], "a": 2, "e": "Rule: ×3 then −1. So ? = 1094.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n5, 14, 41, 122, 365, ?", "oh": ["730", "1097", "1094", "1099"], "eh": "नियम: ×3 फिर −1। इसलिए ? = 1094।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'NIGHT' is coded as 67. How will 'CANDY' be coded in that language?", "o": ["66", "47", "57", "56"], "a": 3, "e": "Code = sum of letter positions + 9. For CANDY: 56.", "qh": "एक कोड भाषा में 'NIGHT' को 67 लिखा जाता है। उसी भाषा में 'CANDY' को कैसे लिखा जाएगा?", "oh": ["66", "47", "57", "56"], "eh": "कोड = अक्षरों की स्थितियों का योग + 9। CANDY के लिए: 56।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n8 9 H 1 A 7 I S © I 1 6 & L 1 Q Q * D 9 1 E\nHow many letters are there in the arrangement, each of which is immediately followed by a number but NOT immediately preceded by a symbol?", "o": ["2", "4", "3", "1"], "a": 0, "e": "Matching places: 9H1, 1A7 → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n8 9 H 1 A 7 I S © I 1 6 & L 1 Q Q * D 9 1 E\nइस क्रम में ऐसे कितने अक्षर हैं, जिनके ठीक बाद एक संख्या है, पर ठीक पहले चिह्न नहीं है?", "oh": ["2", "4", "3", "1"], "eh": "शर्त पूरी करने वाले स्थान: 9H1, 1A7 → 2।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\nR L 8 % $ € O P 3 2 # 3 R J % € 8 S D $ N 8\nHow many odd numbers are there in the arrangement, each of which is immediately preceded by a symbol?", "o": ["3", "1", "4", "2"], "a": 1, "e": "Matching places: #3R → 1.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\nR L 8 % $ € O P 3 2 # 3 R J % € 8 S D $ N 8\nइस क्रम में ऐसी कितनी विषम संख्याएँ हैं, जिनके ठीक पहले एक चिह्न है?", "oh": ["3", "1", "4", "2"], "eh": "शर्त पूरी करने वाले स्थान: #3R → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of students, Deepak is 23th from the left end and 13th from the right end. How many students are there in the row?", "o": ["37", "35", "36", "34"], "a": 1, "e": "Total = 23 + 13 − 1 = 35.", "qh": "छात्रों की एक पंक्ति में दीपक बाएँ छोर से 23वें और दाएँ छोर से 13वें स्थान पर है। पंक्ति में कितने छात्र हैं?", "oh": ["37", "35", "36", "34"], "eh": "कुल = 23 + 13 − 1 = 35।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nJ49Z, N64W, R81T, V100Q, ?", "o": ["Z121N", "Z123N", "A121N", "Z120N"], "a": 0, "e": "First letter +4; number: consecutive squares; last letter -3. So ? = Z121N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nJ49Z, N64W, R81T, V100Q, ?", "oh": ["Z121N", "Z123N", "A121N", "Z120N"], "eh": "पहला अक्षर +4; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -3। इसलिए ? = Z121N।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n3 : 9 :: 10 : ?", "o": ["110", "101", "100", "120"], "a": 2, "e": "Rule: x → x². 3 → 9, so 10 → 100.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n3 : 9 :: 10 : ?", "oh": ["110", "101", "100", "120"], "eh": "नियम: x → x²। 3 → 9, इसलिए 10 → 100।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["3 – 24", "7 – 336", "6 – 210", "9 – 738"], "a": 3, "e": "In all except 9 – 738: second = (first)³ − first.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["3 – 24", "7 – 336", "6 – 210", "9 – 738"], "eh": "9 – 738 को छोड़कर सभी में: दूसरी = (पहली)³ − पहली।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Iron", "Copper", "Silver", "Wood"], "a": 3, "e": "Wood is not a metal.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["लोहा", "ताँबा", "चाँदी", "लकड़ी"], "eh": "लकड़ी धातु नहीं है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Which letter is 11th from the right end of the English alphabet?", "o": ["P", "Q", "O", "R"], "a": 0, "e": "Right 11th letter = P.", "qh": "अंग्रेज़ी वर्णमाला में दाएँ छोर से 11वाँ अक्षर कौन-सा है?", "oh": ["P", "Q", "O", "R"], "eh": "दाएँ से 11वाँ अक्षर = P।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "Which two mathematical signs should be interchanged to make the following equation correct?\n20 + 2 ÷ 4 × 4 − 10 = 4", "o": ["+ and ÷", "+ and −", "+ and ×", "× and ÷"], "a": 2, "e": "Interchanging + and ×: 20 × 2 ÷ 4 + 4 − 10 = 4. ✔", "qh": "नीचे दिए समीकरण को सही बनाने के लिए किन दो गणितीय चिह्नों को आपस में बदलना होगा?\n20 + 2 ÷ 4 × 4 − 10 = 4", "oh": ["+ और ÷", "+ और −", "+ और ×", "× और ÷"], "eh": "+ और × बदलने पर: 20 × 2 ÷ 4 + 4 − 10 = 4। ✔", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Railways", "q": "Which Indian Railways production unit at Varanasi was earlier called the Diesel Locomotive Works?", "o": ["Chittaranjan Locomotive Works", "Patiala Locomotive Works", "Rail Coach Factory", "Banaras Locomotive Works"], "a": 3, "e": "DLW Varanasi (1961) was renamed Banaras Locomotive Works in 2020 and now builds electric locomotives.", "qh": "वाराणसी की कौन-सी भारतीय रेलवे उत्पादन इकाई पहले डीज़ल लोकोमोटिव वर्क्स कहलाती थी?", "oh": ["चित्तरंजन लोकोमोटिव वर्क्स", "पटियाला लोकोमोटिव वर्क्स", "रेल कोच फ़ैक्ट्री", "बनारस लोकोमोटिव वर्क्स"], "eh": "DLW वाराणसी (1961) का नाम 2020 में बनारस लोकोमोटिव वर्क्स कर दिया गया; अब यह बिजली के इंजन बनाती है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "Who was the first Chief Election Commissioner of India?", "o": ["T. N. Seshan", "K. V. K. Sundaram", "Sukumar Sen", "S. P. Sen Verma"], "a": 2, "e": "Sukumar Sen conducted the first general elections of 1951–52.", "qh": "भारत के पहले मुख्य चुनाव आयुक्त कौन थे?", "oh": ["टी. एन. शेषन", "के. वी. के. सुंदरम", "सुकुमार सेन", "एस. पी. सेन वर्मा"], "eh": "सुकुमार सेन ने 1951–52 के पहले आम चुनाव करवाए।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "In October 2026, Veerangana Durgavati Tiger Reserve became the third habitat for cheetahs in Madhya Pradesh. Which were the first two?", "o": ["Kanha and Pench", "Bandhavgarh and Satpura", "Panna and Ratapani", "Kuno National Park and Gandhi Sagar Wildlife Sanctuary"], "a": 3, "e": "Botswana cheetahs Vyom and Neera were released at Veerangana Durgavati TR after Kuno (from 2022) and Gandhi Sagar.", "qh": "अक्टूबर 2026 में वीरांगना दुर्गावती टाइगर रिज़र्व मध्य प्रदेश में चीतों का तीसरा ठिकाना बना। पहले दो कौन-से थे?", "oh": ["कान्हा और पेंच", "बांधवगढ़ और सतपुड़ा", "पन्ना और रातापानी", "कूनो राष्ट्रीय उद्यान और गांधी सागर वन्यजीव अभयारण्य"], "eh": "कूनो (2022 से) और गांधी सागर के बाद बोत्सवाना के चीते व्योम और नीरा वीरांगना दुर्गावती टाइगर रिज़र्व में छोड़े गए।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "Which Article of the Constitution gives High Courts the power to issue writs?", "o": ["Article 226", "Article 32", "Article 227", "Article 136"], "a": 0, "e": "Article 226 empowers High Courts to issue writs for Fundamental Rights and other purposes; Article 32 is for the Supreme Court.", "qh": "संविधान का कौन-सा अनुच्छेद उच्च न्यायालयों को रिट जारी करने की शक्ति देता है?", "oh": ["अनुच्छेद 226", "अनुच्छेद 32", "अनुच्छेद 227", "अनुच्छेद 136"], "eh": "अनुच्छेद 226 उच्च न्यायालयों को मौलिक अधिकारों और अन्य कामों के लिए रिट जारी करने की शक्ति देता है; अनुच्छेद 32 सुप्रीम कोर्ट के लिए है।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "The Kisan Credit Card (KCC) scheme, introduced in 1998, mainly helps farmers to:", "o": ["Insure their cattle", "Sell crops online", "Buy tractors at subsidised prices", "Get short-term crop loans easily"], "a": 3, "e": "KCC gives farmers a revolving credit limit for crop inputs and other short-term needs, mostly through banks; it was launched on NABARD's recommendation.", "qh": "1998 में शुरू हुई किसान क्रेडिट कार्ड (KCC) योजना मुख्य रूप से किसानों की किस काम में मदद करती है?", "oh": ["पशुओं का बीमा कराने में", "फ़सल ऑनलाइन बेचने में", "सस्ते दाम पर ट्रैक्टर खरीदने में", "आसानी से अल्पकालिक फ़सल ऋण पाने में"], "eh": "KCC किसानों को बीज-खाद जैसी फ़सल ज़रूरतों के लिए बैंकों से घूमती (रिवॉल्विंग) कर्ज़ सीमा देता है; यह नाबार्ड की सिफ़ारिश पर शुरू हुआ।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Geography", "q": "Guru Shikhar, the highest peak of the Aravalli Range, is in which state?", "o": ["Gujarat", "Rajasthan", "Haryana", "Madhya Pradesh"], "a": 1, "e": "Guru Shikhar (1,722 m) is near Mount Abu in Sirohi district, Rajasthan.", "qh": "अरावली पर्वतमाला की सबसे ऊँची चोटी गुरु शिखर किस राज्य में है?", "oh": ["गुजरात", "राजस्थान", "हरियाणा", "मध्य प्रदेश"], "eh": "गुरु शिखर (1,722 m) राजस्थान के सिरोही ज़िले में माउंट आबू के पास है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "The Santosh Trophy is a national championship in which sport?", "o": ["Hockey", "Cricket", "Volleyball", "Football"], "a": 3, "e": "The Santosh Trophy is India's senior national football championship for state teams, started in 1941.", "qh": "संतोष ट्रॉफ़ी किस खेल की राष्ट्रीय प्रतियोगिता है?", "oh": ["हॉकी", "क्रिकेट", "वॉलीबॉल", "फ़ुटबॉल"], "eh": "संतोष ट्रॉफ़ी 1941 से राज्यों की टीमों के बीच होने वाली भारत की सीनियर राष्ट्रीय फ़ुटबॉल प्रतियोगिता है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Geography", "q": "The Kudremukh and Bailadila ranges are famous for deposits of:", "o": ["Coal", "Iron ore", "Bauxite", "Copper"], "a": 1, "e": "Kudremukh (Karnataka) and Bailadila (Chhattisgarh) are known for high-grade iron ore.", "qh": "कुद्रेमुख और बैलाडीला पहाड़ियाँ किसके भंडार के लिए प्रसिद्ध हैं?", "oh": ["कोयला", "लौह अयस्क", "बॉक्साइट", "तांबा"], "eh": "कुद्रेमुख (कर्नाटक) और बैलाडीला (छत्तीसगढ़) उच्च गुणवत्ता वाले लौह अयस्क के लिए जाने जाते हैं।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Awards", "q": "Which artist won the Album of the Year at the Grammy Awards 2026?", "o": ["Bad Bunny", "Taylor Swift", "Beyoncé", "Billie Eilish"], "a": 0, "e": "Bad Bunny won Album of the Year for 'Debí Tirar Más Fotos', the first Spanish-language album to win the award.", "qh": "ग्रैमी अवॉर्ड्स 2026 में 'एल्बम ऑफ़ द ईयर' किस कलाकार को मिला?", "oh": ["बैड बनी", "टेलर स्विफ़्ट", "बियॉन्से", "बिली आइलिश"], "eh": "बैड बनी को 'Debí Tirar Más Fotos' के लिए एल्बम ऑफ़ द ईयर मिला — यह पुरस्कार जीतने वाला पहला स्पेनिश भाषा का एल्बम।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Railways", "q": "The new Dedicated Freight Corridor announced in the Union Budget 2026-27 will connect Dankuni in West Bengal to:", "o": ["Ludhiana", "Surat", "Dadri", "Mumbai"], "a": 1, "e": "Along with seven high-speed rail corridors, the Budget announced a new DFC from Dankuni (West Bengal) to Surat (Gujarat).", "qh": "केंद्रीय बजट 2026-27 में घोषित नया डेडिकेटेड फ़्रेट कॉरिडोर पश्चिम बंगाल के डानकुनी को किससे जोड़ेगा?", "oh": ["लुधियाना", "सूरत", "दादरी", "मुंबई"], "eh": "सात हाई-स्पीड रेल कॉरिडोर के साथ बजट में डानकुनी (पश्चिम बंगाल) से सूरत (गुजरात) तक नए DFC की घोषणा हुई।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "The Lok Sabha is also known as the:", "o": ["Council of States", "House of Lords", "Legislative Council", "House of the People"], "a": 3, "e": "The Lok Sabha is the House of the People; the Rajya Sabha is the Council of States.", "qh": "लोकसभा को और किस नाम से जाना जाता है?", "oh": ["राज्यों की परिषद (Council of States)", "हाउस ऑफ़ लॉर्ड्स", "विधान परिषद", "जनता का सदन (House of the People)"], "eh": "लोकसभा 'जनता का सदन' है; राज्यसभा 'राज्यों की परिषद' है।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Who became the 27th Chief of the Naval Staff on 31 May 2026?", "o": ["Admiral Dinesh K. Tripathi", "Admiral R. Hari Kumar", "Admiral Krishna Swaminathan", "Vice Admiral Sanjay Vatsayan"], "a": 2, "e": "Admiral Krishna Swaminathan took charge as the 27th Chief of the Naval Staff on 31 May 2026.", "qh": "31 मई 2026 को 27वें नौसेना प्रमुख कौन बने?", "oh": ["एडमिरल दिनेश के. त्रिपाठी", "एडमिरल आर. हरि कुमार", "एडमिरल कृष्णा स्वामीनाथन", "वाइस एडमिरल संजय वत्सायन"], "eh": "एडमिरल कृष्णा स्वामीनाथन ने 31 मई 2026 को 27वें नौसेना प्रमुख का पदभार संभाला।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Static GK", "q": "Teachers' Day in India (5 September) marks the birth anniversary of:", "o": ["Dr Zakir Husain", "Savitribai Phule", "Dr Rajendra Prasad", "Dr S. Radhakrishnan"], "a": 3, "e": "India's second President, Dr Sarvepalli Radhakrishnan, was born on 5 September 1888.", "qh": "भारत में शिक्षक दिवस (5 सितंबर) किसकी जयंती पर मनाया जाता है?", "oh": ["डॉ. ज़ाकिर हुसैन", "सावित्रीबाई फुले", "डॉ. राजेंद्र प्रसाद", "डॉ. एस. राधाकृष्णन"], "eh": "भारत के दूसरे राष्ट्रपति डॉ. सर्वपल्ली राधाकृष्णन का जन्म 5 सितंबर 1888 को हुआ था।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Awards", "q": "The Ashoka Chakra is awarded for:", "o": ["Gallantry in peacetime", "Gallantry in war", "Excellence in sports", "Service in public administration"], "a": 0, "e": "The Ashoka Chakra is India's highest peacetime gallantry award.", "qh": "अशोक चक्र किसके लिए दिया जाता है?", "oh": ["शांतिकाल में वीरता", "युद्धकाल में वीरता", "खेलों में उत्कृष्टता", "लोक प्रशासन में सेवा"], "eh": "अशोक चक्र भारत का सर्वोच्च शांतिकालीन वीरता पुरस्कार है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "History", "q": "The Rowlatt Act (1919), against which Gandhiji launched a satyagraha, allowed the government to:", "o": ["Collect a salt tax", "Partition Bengal", "Imprison people without trial", "Ban the Indian National Congress"], "a": 2, "e": "The Rowlatt Act allowed detention without trial; protests against it led to the Jallianwala Bagh massacre in April 1919.", "qh": "रॉलेट एक्ट (1919), जिसके खिलाफ़ गांधीजी ने सत्याग्रह शुरू किया, सरकार को क्या करने देता था?", "oh": ["नमक कर वसूलना", "बंगाल का विभाजन करना", "बिना मुकदमे लोगों को जेल में डालना", "कांग्रेस पर प्रतिबंध लगाना"], "eh": "रॉलेट एक्ट बिना मुकदमे हिरासत की अनुमति देता था; इसके विरोध के दौरान अप्रैल 1919 में जलियाँवाला बाग हत्याकांड हुआ।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "The 16th Finance Commission (chaired by Arvind Panagariya), whose report was tabled on 1 February 2026, kept the states' share in the divisible pool of central taxes at:", "o": ["42%", "32%", "45%", "41%"], "a": 3, "e": "The 16th FC retained vertical devolution at 41% for 2026-27 to 2030-31 and added a GDP-contribution criterion.", "qh": "16वें वित्त आयोग (अध्यक्ष अरविंद पनगढ़िया), जिसकी रिपोर्ट 1 फ़रवरी 2026 को पेश हुई, ने केंद्रीय करों के विभाज्य पूल में राज्यों का हिस्सा कितना रखा?", "oh": ["42%", "32%", "45%", "41%"], "eh": "16वें वित्त आयोग ने 2026-27 से 2030-31 के लिए राज्यों का हिस्सा 41% ही रखा और GDP योगदान का नया मानदंड जोड़ा।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "History", "q": "Who wrote 'Ain-i-Akbari', an account of Akbar's administration?", "o": ["Abul Fazl", "Faizi", "Badauni", "Birbal"], "a": 0, "e": "Abul Fazl wrote the Akbarnama, whose third volume is the Ain-i-Akbari.", "qh": "अकबर के प्रशासन का वर्णन करने वाली 'आइन-ए-अकबरी' किसने लिखी?", "oh": ["अबुल फ़ज़ल", "फ़ैज़ी", "बदायूँनी", "बीरबल"], "eh": "अबुल फ़ज़ल ने अकबरनामा लिखा, जिसका तीसरा भाग आइन-ए-अकबरी है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Art & Culture", "q": "The harvest festival 'Onam' is mainly celebrated in which state?", "o": ["Karnataka", "Goa", "Kerala", "Andhra Pradesh"], "a": 2, "e": "Onam, with its snake-boat races and pookalam flower carpets, is Kerala's harvest festival.", "qh": "फ़सल का त्योहार 'ओणम' मुख्य रूप से किस राज्य में मनाया जाता है?", "oh": ["कर्नाटक", "गोवा", "केरल", "आंध्र प्रदेश"], "eh": "नाव दौड़ और फूलों की रंगोली (पूकलम) वाला ओणम केरल का फ़सल त्योहार है।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Computer", "q": "What is the full form of 'CPU'?", "o": ["Central Processing Unit", "Central Program Utility", "Computer Personal Unit", "Control Processing Unit"], "a": 0, "e": "The CPU carries out program instructions and is called the brain of the computer.", "qh": "'CPU' का पूरा नाम क्या है?", "oh": ["सेंट्रल प्रोसेसिंग यूनिट", "सेंट्रल प्रोग्राम यूटिलिटी", "कंप्यूटर पर्सनल यूनिट", "कंट्रोल प्रोसेसिंग यूनिट"], "eh": "CPU प्रोग्राम के निर्देश चलाता है और इसे कंप्यूटर का दिमाग कहा जाता है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "Who won the Golden Ball for the best player at the FIFA World Cup 2026?", "o": ["Kylian Mbappé", "Lionel Messi", "Rodri", "Lamine Yamal"], "a": 2, "e": "Spain's captain Rodri won the Golden Ball after Spain beat Argentina 1–0 (a.e.t.) in the final at New York New Jersey Stadium on 19 July 2026. (World Cup: 11 June–19 July 2026, USA–Canada–Mexico.)", "qh": "फ़ीफ़ा विश्व कप 2026 में सर्वश्रेष्ठ खिलाड़ी का गोल्डन बॉल किसे मिला?", "oh": ["किलियन एम्बाप्पे", "लियोनेल मेसी", "रोड्री", "लामिन यामल"], "eh": "19 जुलाई 2026 को न्यूयॉर्क न्यूजर्सी स्टेडियम में फ़ाइनल में स्पेन ने अर्जेंटीना को 1–0 (अतिरिक्त समय) से हराया; कप्तान रोड्री को गोल्डन बॉल मिला। (विश्व कप: 11 जून–19 जुलाई 2026, अमेरिका–कनाडा–मेक्सिको।)", "level": "medium"}]});
